// 沿 SVG 曲线近点吸附铜丝，完成轮廓后支持触控与键盘点蓝。
import{updateProgress}from'./common.js';import{toast}from'../main.js';
const svg=document.querySelector('#wire-art'),petals=[...svg.querySelectorAll('[data-petal]')];
const samples=petals.map(path=>Array.from({length:41},(_,i)=>{const p=path.getPointAtLength(path.getTotalLength()*i/40);return new DOMPoint(p.x,p.y).matrixTransform(path.transform.baseVal.consolidate().matrix);}));
for(const path of petals){const guide=path.cloneNode();for(const attr of['data-petal','tabindex','role','aria-label'])guide.removeAttribute(attr);guide.setAttribute('fill','none');guide.setAttribute('stroke','#c7b26b33');guide.setAttribute('aria-hidden','true');guide.style.pointerEvents='none';svg.insertBefore(guide,petals[0]);}
let progress=Array(7).fill(40),filled=new Set(Array.from({length:7},(_,i)=>i)),started=false,active=false,color='#4b8392';
function status(){const total=progress.reduce((sum,value)=>sum+value,0);const percent=Math.round(total/280*100);updateProgress(percent,total<280?`掐丝 ${percent}% · 沿轮廓移动，或按“接一段金丝”`:`轮廓已成 · 已点蓝 ${filled.size}/7 片花瓣`);document.querySelector('#advance-craft').innerHTML=total<280?'接一段金丝 ＋':'为下一瓣点蓝 ＋';}
function render(){petals.forEach((path,i)=>{const length=path.getTotalLength();path.style.strokeDasharray=String(length);path.style.strokeDashoffset=String(length*(1-progress[i]/40));path.setAttribute('fill',filled.has(i)?color:'#173b40');});status();}
function reset(){started=true;progress=Array(7).fill(0);filled=new Set();render();}
function advance(){if(!started)reset();const index=progress.findIndex(value=>value<40);if(index>=0)progress[index]=40;else{const empty=petals.findIndex((_,i)=>!filled.has(i));if(empty>=0)filled.add(empty);}render();if(filled.size===7)toast('金丝成纹，七瓣已点蓝。');}
function fill(index){if(progress.some(value=>value<40)){toast('先完成金丝轮廓，再为花瓣点蓝。');return;}filled.add(index);render();}
function trace(event){const local=new DOMPoint(event.clientX,event.clientY).matrixTransform(svg.getScreenCTM().inverse());let closest={distance:Infinity,index:0,step:0};samples.forEach((points,index)=>points.forEach((point,step)=>{const distance=Math.hypot(point.x-local.x,point.y-local.y);if(distance<closest.distance)closest={distance,index,step};}));if(closest.distance<=12){progress[closest.index]=Math.max(progress[closest.index],Math.min(40,closest.step+5));render();}}
svg.addEventListener('pointerdown',event=>{if(!started)reset();else if(progress.every(value=>value===40)){const petal=event.target.closest('[data-petal]');if(petal)fill(Number(petal.dataset.petal));return;}active=true;svg.setPointerCapture(event.pointerId);trace(event);});svg.addEventListener('pointermove',event=>{if(active)trace(event);});svg.addEventListener('pointerup',()=>active=false);svg.addEventListener('pointercancel',()=>active=false);petals.forEach((path,i)=>path.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();if(progress.every(value=>value===40)&&started)fill(i);else advance();}}));document.querySelector('#advance-craft').addEventListener('click',advance);document.querySelector('#reset-craft').addEventListener('click',reset);document.querySelectorAll('[data-enamel]').forEach(button=>button.addEventListener('click',()=>{color=button.dataset.enamel;document.querySelectorAll('[data-enamel]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));if(started)render();}));
